# Function-only observer support. The early full baseline is deliberately
# unadmitted evidence; only the later product route has a plan/ticket inspector.
function AssertLargeFullBaselineEnvelope($Profile,$Basis,$Expected,$Native,[string]$ExpectedPath,[string]$BasisPath,[string]$NativePath){
 Need ($ExpectedPath-ceq(Join-Path $c.stage 'lab-full-content-baseline.json')-and$BasisPath-ceq(Join-Path $c.stage 'lab-baseline-source-basis.json')-and$NativePath-ceq(Join-Path $c.stage 'lab-fresh-native-source.json')) 'Full-baseline exception is restricted to the three pinned copied evidence roles.'
 $a=LabV3Descriptor $Profile
 foreach($name in @('schema_version','raw_identities','files','directories','data_streams','object_slots','raw_identity_slots','data_stream_slots','maximum_expected_tree_bytes','maximum_inspection_bytes','maximum_native_report_bytes','projected_owned_handle_slots','maximum_owned_handle_slots','maximum_constructor_input_metadata_bytes')){$null=LabIntegerKey $a.$name}
 $files=@($Expected.objects|Where-Object {-not$_.directory}).Count;$dirs=@($Expected.objects|Where-Object {$_.directory}).Count;$streams=$files
 foreach($o in $Expected.objects){$p=$o.PSObject.Properties['named_streams'];if($null-ne$p){$streams+=@($p.Value).Count}}
 $units=@($a.source_inspection_sha256);Need ($units.Count-eq32-and@($units|Where-Object {$_-lt0-or$_-gt255}).Count-eq0) 'Exact full-baseline source inspection pin required.'
 $pin=([BitConverter]::ToString([byte[]]$units)).Replace('-','').ToLowerInvariant();$objects=$files+$dirs
 $remaining=[long]$a.maximum_owned_handle_slots-2L*$streams-8L;$slots=[Math]::Min([long]$a.raw_identities,$remaining)
 Need ($a.schema_version-eq2-and$files-eq811-and$dirs-eq723-and$objects-eq1534-and$streams-eq811-and$a.raw_identities-eq@($Basis.ntfs.files).Count-and$a.files-eq$files-and$a.directories-eq$dirs-and$a.data_streams-eq$streams-and$objects-eq@($Expected.objects).Count-and$objects-le$a.object_slots-and$a.object_slots-eq$slots-and$a.object_slots-gt1280-and$a.object_slots-le2048-and$a.raw_identities-le$a.raw_identity_slots-and$a.raw_identity_slots-le2048-and$a.raw_identity_slots-gt0-and$a.data_streams-le$a.data_stream_slots-and$a.data_stream_slots-le16384-and$a.data_stream_slots-gt0-and$pin-ceq$Basis.canonical_inspection_sha256-and$pin-ceq$Native.request.source_inspection_sha256-and$a.raw_identities-eq@($Native.request.files).Count-and(SameJsonValue $Profile $Native.request.resource_profile)) 'Complete >1280 baseline raw/native/canonical counts or inventory pin differ.'
 Need ($a.maximum_expected_tree_bytes-gt0-and$a.maximum_expected_tree_bytes-le16MB-and(Get-Item -LiteralPath $ExpectedPath).Length-le$a.maximum_expected_tree_bytes-and$a.maximum_constructor_input_metadata_bytes-gt0-and$a.maximum_constructor_input_metadata_bytes-le16MB-and$a.maximum_inspection_bytes-gt0-and$a.maximum_inspection_bytes-le64MB-and(Get-Item -LiteralPath $BasisPath).Length-le$a.maximum_inspection_bytes-and$a.maximum_native_report_bytes-gt0-and$a.maximum_native_report_bytes-le64MB-and(Get-Item -LiteralPath $NativePath).Length-le$a.maximum_native_report_bytes-and$a.projected_owned_handle_slots-eq($objects+2*$streams+8)-and$a.projected_owned_handle_slots-le$a.maximum_owned_handle_slots-and$a.maximum_owned_handle_slots-le34056) 'Full baseline semantic bytes or actual projected handle ceiling differs.'
 $records=[long]$objects+[long][Math]::Floor([double]$a.maximum_expected_tree_bytes/786432)+2L
 $wire=[long][Math]::Ceiling(4.0*[double]$a.maximum_expected_tree_bytes/3.0)+$records*160L+4194304L+192L
 $expectedBudget=[pscustomobject]@{max_page_bytes=4194304;max_records_per_page=128;max_records=$records;max_pages=$records;max_file_bytes=$wire}
 $mapRecords=[long]$dirs+[long]$streams+1L;$mapBudget=[pscustomobject]@{max_page_bytes=4194304;max_records_per_page=128;max_records=$mapRecords;max_pages=$mapRecords;max_file_bytes=67108864L}
 # Compare parsed JSON numeric representations on both sides, as the original
 # strict comparer also distinguishes CLR numeric types in PowerShell 5.1.
 $expectedBudget=($expectedBudget|ConvertTo-Json -Depth 8)|ConvertFrom-Json;$mapBudget=($mapBudget|ConvertTo-Json -Depth 8)|ConvertFrom-Json
 Need ($a.paged_resources.schema_version-eq1-and$a.paged_resources.expected_chunk_bytes-eq786432-and(SameJsonValue $a.paged_resources.expected_tree_pages $expectedBudget)-and(SameJsonValue $a.paged_resources.recovery_map_pages $mapBudget)) 'Canonical independently derived full-baseline page budgets differ.'
 $m=Json (Join-Path $c.stage 'lab-fresh-baseline-manifest.json');$receipt=Json (Join-Path $c.stage 'lab-baseline-expectation-pages.json')
 Need ($m.schema_version-eq2-and$m.kind-ceq'lab-full-source-content-baseline-pages-v2'-and$m.paged_metadata_lab_mode-eq$true-and$m.complete_paged_expected_domain_verified-eq$true-and$m.source_admitted-eq$false-and$m.certificate_issued-eq$false-and$m.conversion_authorized-eq$false-and$m.replay_authorized-eq$false-and(SameJsonValue $m.expectation_pages $receipt)) 'Full paged baseline must remain explicitly unadmitted producer evidence.'
 $pagePin=$c.fresh_baseline_files.expected_pages;$legacyPin=$c.fresh_baseline_files.expectation
 Need ($receipt.schema_version-eq2-and$receipt.file_sha256-ceq$pagePin.sha256-and$receipt.semantic_sha256-ceq$legacyPin.sha256-and$receipt.objects-eq$objects-and$receipt.records-ge($objects+1)-and$receipt.records-le$records-and$receipt.pages-gt0-and$receipt.pages-le$records-and$receipt.bytes-eq$pagePin.bytes-and$receipt.bytes-le$wire-and$receipt.semantic_byte_budget-eq$a.maximum_expected_tree_bytes-and(SameJsonValue $receipt.page_budget $expectedBudget)) 'Pinned baseline page receipt must reproduce the exact complete legacy expectation pin and resource bounds.'
 $raw=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal);foreach($f in $Basis.ntfs.files){$key=LabRecordKey $f.record_number $f.sequence_number;Need (-not$raw.ContainsKey($key)) 'Duplicate complete baseline raw identity.';$raw.Add($key,$f)}
 $requests=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($f in $Native.request.files){$key=LabRecordKey $f.record_number $f.sequence_number;Need ($raw.ContainsKey($key)-and$requests.Add($key)) 'Baseline native/raw identity coverage differs.'}
 Need ($requests.Count-eq$raw.Count) 'Baseline native/raw complete identity set differs.'
 foreach($o in $Expected.objects){$key=LabRecordKey $o.record_number $o.sequence_number;Need ($raw.ContainsKey($key)-and$requests.Contains($key)-and$raw[$key].is_directory-eq$o.directory) 'Canonical full-baseline identity or type differs from raw/native inventory.'}
 return @{raw_identities=$a.raw_identities;files=$files;directories=$dirs;data_streams=$streams;objects=$objects;source_inspection_sha256=$pin;descriptor=$a;full_paged_baseline_only=$true;source_admitted=$false;product_plan_or_ticket_asserted=$false;constructor_metadata_measurement_claimed=$false}
}
function AssertLabV3Envelope($Profile,$Basis,$Expected,$Native,[string]$ExpectedPath,[string]$BasisPath,[string]$NativePath){
 if($ExpectedPath-ceq(Join-Path $c.stage 'lab-full-content-baseline.json')){return AssertLargeFullBaselineEnvelope $Profile $Basis $Expected $Native $ExpectedPath $BasisPath $NativePath}
 return AssertProductPagedV3Envelope $Profile $Basis $Expected $Native $ExpectedPath $BasisPath $NativePath
}
function AssertLargeAdditionalDirectories($Expected,$Manifest){
 $growth=Json (Join-Path $c.stage 'lab-additional-directory-growth.json')
 Need ($growth.schema_version-eq1-and$growth.kind-ceq'ntfs-paged-directory-object-fixture'-and$growth.success-eq$true-and[guid]$growth.source_parent_checkpoint-eq[guid]'83290a28-1e83-4eb2-a4d3-b0e9f5a8d63b'-and$growth.created_directories-eq450-and$growth.created_payload_files-eq0-and$growth.original_payload_writes-eq0-and$growth.original_payload_bytes_read-eq0-and$growth.extent_moves-eq0-and$growth.source_admitted-eq$false-and$growth.conversion_authorized-eq$false-and$growth.replay_authorized-eq$false-and$null-eq$growth.failure-and$growth.automatic_cleanup_retry_restore-eq$false-and$growth.fixture_root-ceq'F:\n2r-paged-450'-and(SameJsonValue $growth.source_before $growth.source_after)) 'Closed exact metadata-only 450-directory fixture required.'
 $b=$growth.source_before;$source=$Manifest.source_binding
 Need ($b.disk_number-eq1-and[guid]$b.disk_guid-eq[guid]$source.identity.disk_guid-and$b.partition_number-eq2-and[guid]$b.partition_guid-eq[guid]$source.identity.partition_guid-and$b.partition_offset-eq16MB-and$b.partition_bytes-eq52GB-and$b.filesystem-ceq'NTFS'-and$b.cluster_bytes-eq65536-and$b.label-ceq'n2r-stream-source') 'Additional directory fixture source route differs from pinned fresh baseline.'
 $paths=@($growth.created_paths);$set=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);Need ($paths.Count-eq450) 'Complete additional directory path receipt required.'
 foreach($path in $paths){Need ($set.Add([string]$path)-and($path-ceq'F:\n2r-paged-450'-or$path-cmatch'\AF:\\n2r-paged-450\\d[0-9]{4}\z')) 'Unexpected or duplicate additional directory path.';$components=@(([string]$path).Substring(3).Split('\'));$objects=@($Expected.objects|Where-Object {SameArray $_.path $components});Need ($objects.Count-eq1-and$objects[0].directory-and$objects[0].length-eq0) 'Every actual additional directory must exist once in the fresh full canonical baseline.';$named=$objects[0].PSObject.Properties['named_streams'];Need ($null-eq$named-or@($named.Value).Count-eq0) 'Additional directory cannot carry named data.'}
 for($i=0;$i-lt449;$i++){Need ($set.Contains(('F:\n2r-paged-450\d{0:D4}'-f$i))) 'Missing additional directory ordinal.'}
 Need ($set.Contains('F:\n2r-paged-450')) 'Additional directory root absent.'
 return @{created_directories=450;created_payload_files=0;all_receipted_directories_in_full_source=$true;original_811_content_checks_unchanged=$true;grants_product_authority=$false}
}
